'use client'

import { forwardRef, useId, type ComponentPropsWithoutRef, type ReactNode } from 'react'
import { HugeiconsIcon } from '@hugeicons/react'
import { ArrowDown01Icon, LanguageSkillIcon } from '@hugeicons/core-free-icons'
import {
  FOOTER_SITEMAP,
  FOOTER_SOCIALS,
  FooterBrand,
  FooterLink,
  FooterSitemap,
  FooterSocialLinks,
  type FooterColumnItem,
  type FooterSocialItem,
} from '@/components/blocks/footer/footer'
import { useControlledState } from '@/lib/hooks/use-controlled-state'
import { cn } from '@/lib/utils'

export type FooterLanguageOption = { value: string; label: string }

const DEFAULT_LANGUAGES: FooterLanguageOption[] = [
  { value: 'en', label: 'English' },
  { value: 'hi', label: 'हिन्दी' },
  { value: 'ja', label: '日本語' },
  { value: 'es', label: 'Español' },
]

export interface FooterLanguageProps extends ComponentPropsWithoutRef<'footer'> {
  brand?: ReactNode
  columns?: FooterColumnItem[]
  socials?: FooterSocialItem[]
  languages?: FooterLanguageOption[]
  language?: string
  defaultLanguage?: string
  onLanguageChange?: (value: string) => void
  languageLabel?: string
  cookieLabel?: string
  cookieHref?: string
  copyright?: ReactNode
}

export const FooterLanguage = forwardRef<HTMLElement, FooterLanguageProps>(
  (
    {
      brand = <FooterBrand />,
      columns = FOOTER_SITEMAP,
      socials = FOOTER_SOCIALS,
      languages = DEFAULT_LANGUAGES,
      language,
      defaultLanguage = 'en',
      onLanguageChange,
      languageLabel = 'Language',
      cookieLabel = 'Cookie settings',
      cookieHref = '#',
      copyright = '© 2026 Nexvyn',
      className,
      ...props
    },
    ref,
  ) => {
    const selectId = useId()
    const [current, setCurrent] = useControlledState(language, defaultLanguage, onLanguageChange)

    return (
      <footer
        ref={ref}
        className={cn('w-full border-t border-(--color-border) bg-(--color-bg)', className)}
        {...props}
      >
        <div className="mx-auto grid max-w-5xl gap-12 px-6 py-12 sm:px-8 lg:grid-cols-[1fr_2fr] lg:gap-16">
          <div className="flex flex-col items-start gap-6">
            <div className="flex flex-col items-start gap-2">
              {brand}
              <FooterSocialLinks items={socials} className="-ms-3" />
            </div>
            <div className="flex flex-col gap-2">
              <label htmlFor={selectId} className="sr-only">
                {languageLabel}
              </label>
              <div className="relative">
                <HugeiconsIcon
                  icon={LanguageSkillIcon}
                  size={16}
                  strokeWidth={1.5}
                  aria-hidden="true"
                  className="pointer-events-none absolute start-3 top-1/2 -translate-y-1/2 text-(--color-muted)"
                />
                <select
                  id={selectId}
                  value={current}
                  onChange={(event) => setCurrent(event.target.value)}
                  className="h-11 w-44 cursor-pointer appearance-none rounded-md border border-(--color-border) bg-transparent ps-9 pe-9 text-sm text-(--color-fg) transition-colors duration-(--motion-dur-fast) ease hover:border-(--color-border-strong) focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent) motion-reduce:transition-none"
                >
                  {languages.map((option) => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
                <HugeiconsIcon
                  icon={ArrowDown01Icon}
                  size={16}
                  strokeWidth={1.5}
                  aria-hidden="true"
                  className="pointer-events-none absolute end-3 top-1/2 -translate-y-1/2 text-(--color-muted)"
                />
              </div>
            </div>
            <div className="mt-auto flex flex-col gap-1">
              {cookieLabel && (
                <FooterLink href={cookieHref} className="text-xs">
                  {cookieLabel}
                </FooterLink>
              )}
              {copyright && <p className="text-xs leading-5 text-(--color-muted)">{copyright}</p>}
            </div>
          </div>
          <FooterSitemap columns={columns} />
        </div>
      </footer>
    )
  },
)
FooterLanguage.displayName = 'FooterLanguage'

'use client'

import { forwardRef, type ComponentPropsWithoutRef, type ReactNode } from 'react'
import { Slot } from '@radix-ui/react-slot'
import { HugeiconsIcon } from '@hugeicons/react'
import { GithubIcon, NewTwitterIcon } from '@hugeicons/core-free-icons'
import { cn } from '@/lib/utils'

export type FooterLinkItem = { label: string; href: string }
export type FooterColumnItem = { title: string; links: FooterLinkItem[] }
export type FooterSocialItem = { label: string; href: string; icon: ReactNode }

export const FOOTER_SOCIALS: FooterSocialItem[] = [
  {
    label: 'GitHub',
    href: '#',
    icon: <HugeiconsIcon icon={GithubIcon} size={18} strokeWidth={1.5} />,
  },
  {
    label: 'X',
    href: '#',
    icon: <HugeiconsIcon icon={NewTwitterIcon} size={18} strokeWidth={1.5} />,
  },
]

export interface FooterLinkProps extends ComponentPropsWithoutRef<'a'> {
  asChild?: boolean
}

export const FooterLink = forwardRef<HTMLAnchorElement, FooterLinkProps>(
  ({ asChild, className, ...props }, ref) => {
    const Comp = asChild ? Slot : 'a'

    return (
      <Comp
        ref={ref}
        className={cn(
          'inline-flex items-center rounded-md text-sm text-(--color-muted) transition-colors duration-(--motion-dur-fast) ease hover:text-(--color-fg) focus-visible:text-(--color-fg) focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent) motion-reduce:transition-none [@media(hover:none)]:min-h-11',
          className,
        )}
        {...props}
      />
    )
  },
)
FooterLink.displayName = 'FooterLink'

export function FooterSocialLinks({
  items,
  className,
}: {
  items: FooterSocialItem[]
  className?: string
}) {
  if (items.length === 0) return null

  return (
    <ul className={cn('flex items-center gap-1', className)}>
      {items.map((item) => (
        <li key={item.label}>
          <a
            href={item.href}
            aria-label={item.label}
            className="flex size-11 items-center justify-center rounded-md text-(--color-muted) transition-colors duration-(--motion-dur-fast) ease hover:bg-(--color-fg)/5 hover:text-(--color-fg) focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent) motion-reduce:transition-none"
          >
            <span aria-hidden="true" className="inline-flex">
              {item.icon}
            </span>
          </a>
        </li>
      ))}
    </ul>
  )
}

export function FooterColumn({ title, links }: FooterColumnItem) {
  return (
    <div>
      <h2 className="text-sm leading-6 text-(--color-fg)">{title}</h2>
      <ul className="mt-3 flex flex-col gap-2">
        {links.map((link) => (
          <li key={link.label}>
            <FooterLink href={link.href}>{link.label}</FooterLink>
          </li>
        ))}
      </ul>
    </div>
  )
}

export function FooterBrand({ children = 'Nexvyn UI' }: { children?: ReactNode }) {
  return <span className="text-base leading-6 text-(--color-fg)">{children}</span>
}

export const FOOTER_SITEMAP: FooterColumnItem[] = [
  {
    title: 'Library',
    links: [
      { label: 'Components', href: '#' },
      { label: 'Blocks', href: '#' },
      { label: 'Illustrations', href: '#' },
      { label: 'Changelog', href: '#' },
    ],
  },
  {
    title: 'Guides',
    links: [
      { label: 'Installation', href: '#' },
      { label: 'Theming', href: '#' },
      { label: 'MCP setup', href: '#' },
    ],
  },
  {
    title: 'Project',
    links: [
      { label: 'GitHub', href: '#' },
      { label: 'Feedback', href: '#' },
      { label: 'Design language', href: '#' },
    ],
  },
  {
    title: 'Legal',
    links: [
      { label: 'License', href: '#' },
      { label: 'Privacy', href: '#' },
      { label: 'Terms', href: '#' },
    ],
  },
]

export const FOOTER_LEGAL: FooterLinkItem[] = [
  { label: 'Privacy', href: '#' },
  { label: 'Terms', href: '#' },
]

export function FooterSitemap({
  columns,
  className,
}: {
  columns: FooterColumnItem[]
  className?: string
}) {
  return (
    <div className={cn('grid grid-cols-2 gap-x-8 gap-y-10 sm:grid-cols-4', className)}>
      {columns.map((column) => (
        <FooterColumn key={column.title} {...column} />
      ))}
    </div>
  )
}

export function FooterBottomBar({
  copyright,
  links,
  label = 'Legal',
  className,
}: {
  copyright?: ReactNode
  links: FooterLinkItem[]
  label?: string
  className?: string
}) {
  return (
    <div
      className={cn(
        'flex flex-col gap-3 border-t border-(--color-border) py-6 sm:flex-row sm:items-center sm:justify-between',
        className,
      )}
    >
      {copyright && <p className="text-xs leading-5 text-(--color-muted)">{copyright}</p>}
      {links.length > 0 && (
        <nav aria-label={label}>
          <ul className="flex items-center gap-6">
            {links.map((link) => (
              <li key={link.label}>
                <FooterLink href={link.href} className="text-xs">
                  {link.label}
                </FooterLink>
              </li>
            ))}
          </ul>
        </nav>
      )}
    </div>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'

export function useControlledState<T>(
  value: T | undefined,
  defaultValue: T,
  onChange?: (next: T) => void,
): [T, (next: T) => void] {
  const [inner, setInner] = useState(defaultValue)
  const isControlled = value !== undefined
  const current = isControlled ? value : inner
  const onChangeRef = useRef(onChange)

  useEffect(() => {
    onChangeRef.current = onChange
  })

  const set = useCallback(
    (next: T) => {
      if (!isControlled) setInner(next)
      onChangeRef.current?.(next)
    },
    [isControlled],
  )

  return [current, set]
}
